import{_ as o,a0 as s,w as r,s as p,ao as u,I as l,x as t,a1 as i,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const A=JSON.parse('{"title":"怎样使用linux的iptables工具进行网络共享 | LCTT x X-CMD","titleTemplate":false,"description":"怎样使用linux的iptables工具进行网络共享 | LCTT (201406) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"怎样使用linux的iptables工具进行网络共享 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"怎样使用linux的iptables工具进行网络共享 | LCTT (201406) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201406/20140610 How to set up Internet connection sharing with iptables on Linux","title":"怎样使用linux的iptables工具进行网络共享","tag":"201406","desc":""},"relativePath":"201406/20140610 How to set up Internet connection sharing with iptables on Linux.md","filePath":"[post].md"}'),d={name:"201406/20140610 How to set up Internet connection sharing with iptables on Linux.md"};function h(x,e,c,b,T,P){const n=s("Link");return r(),p("div",null,[e[11]||(e[11]=u(`<h1 id="怎样使用linux的iptables工具进行网络共享" tabindex="-1">怎样使用linux的iptables工具进行网络共享 <a class="header-anchor" href="#怎样使用linux的iptables工具进行网络共享" aria-label="Permalink to “怎样使用linux的iptables工具进行网络共享”">​</a></h1><p>在本教程中，我将解释多个设备怎样在linux下共享一个网络连接。目前无线路由器已经成为主流的消费品，从而解决了本文这一问题。这里假设你家中并没有一台无线路由器，不过，你却有一台已经有&quot;猫&quot;和有线网卡的的linux主机。&quot;猫&quot;是以动态公有IP地址的模式连接到互联网，主机的网卡连接到你的交换机或者集线器。其他设备（如linux或者windows的PC或者笔记本）以网桥的形式连接，并且没有连接到互联网。为了共享linux主机的互联网，你必须把主机转换成网关，以便它能实现从其他设备中传送和接受信息。</p><h3 id="术语字汇" tabindex="-1">术语字汇 <a class="header-anchor" href="#术语字汇" aria-label="Permalink to “术语字汇”">​</a></h3><ul><li><strong>私有IP地址</strong>（路由不可达地址）是一个被用于本地局域网的IP地址（在互联网中不可见）。</li><li><strong>公用IP地址</strong>（路由可达地址）是一个在互联网中可见的IP地址。</li><li><strong>IP伪装</strong>是一项允许一系列机器通过MASQ网关连接互联网的功能。这些MASQ网关之外的机器在互联网中是不可见的。MASQ之后的机器中任何流入或流出的数据必须经过MASQ网关。</li><li><strong>网络地址转换</strong>（NAT）是一项通过IP伪装技术可以使私有IP地址访问互联网的功能。</li></ul><h3 id="hardware-requirements" tabindex="-1">Hardware Requirements <a class="header-anchor" href="#hardware-requirements" aria-label="Permalink to “Hardware Requirements”">​</a></h3><p>硬件要求</p><ul><li>一台有两个接口（一个公有IP地址和其他的私有IP地址）的linux主机，这个主机将被用作网关。</li><li>一台或者多台拥有私有IP地址的linux/windows系统的PC或者笔记本。</li><li>交换机/集线器（可选）。</li></ul><h3 id="教程步骤" tabindex="-1">教程步骤 <a class="header-anchor" href="#教程步骤" aria-label="Permalink to “教程步骤”">​</a></h3><p>接下来的过程需要在linux主机（用于共享的网关）上完成。</p><h4 id="_1、激活ip转发" tabindex="-1">1、激活IP转发 <a class="header-anchor" href="#_1、激活ip转发" aria-label="Permalink to “1、激活IP转发”">​</a></h4><p>为了设置网络共享，你需要在linux主机上更改一个内核参数来使能IP转发功能。内核启动参数设定在/etc/sysctl.conf文件中。</p><p>打开这个文件，定位到含有&quot;# net.ipv4.ip_forward = 0&quot;的这一行，移除#号（即取消注释），然后将其值设置为1，改好之后应该和下面的一致。</p><pre><code>net.ipv4.ip_forward = 1
</code></pre><p>你还要使激活IP转发功能生效，通过执行下面的命令：</p><pre><code>$ sudo sysctl -w net.ipv4.ip_forward=1
$ sudo sysctl -p
</code></pre><h4 id="_2、nat配置" tabindex="-1">2、NAT配置 <a class="header-anchor" href="#_2、nat配置" aria-label="Permalink to “2、NAT配置”">​</a></h4><p>另一个网络共享的重要部分是NAT配置，这可以通过使用iptables的命令，iptables包含四个防火墙的规则表：</p><ul><li>FILTER (默认表格)</li><li>NAT</li><li>MANGLE</li><li>RAW</li></ul><p>这个教程中我们将仅使用两个表格：FILTER和NAT表格。</p><p>首先，刷新所有活跃的防火墙的规则。</p><pre><code>$ sudo iptables -X
$ sudo iptables -F
$ sudo iptables -t nat -X
$ sudo iptables -t nat -F
</code></pre><p>在输入表格中，你需要设置转发链（FORWARD）成可接受的（ACCEPT）目的地，因此所有通过主机的数据包将会被正确的处理。</p><pre><code>$ sudo iptables -I INPUT -m state --state RELATED,ESTABLISHED -j ACCEPT
$ sudo iptables -I FORWARD -m state --state RELATED,ESTABLISHED -j ACCEPT
</code></pre><p>在NAT表中，你必须为你的WAN口启用IP伪装功能，我们假设WAN口协议是ppp0。为了在ppp0接口上使能IP伪造技术，我们使用以下的命令：</p><pre><code>$ sudo iptables -t nat -I POSTROUTING -o ppp0 -j MASQUERADE
</code></pre><h4 id="_3、配置私有ip地址" tabindex="-1">3、配置私有IP地址 <a class="header-anchor" href="#_3、配置私有ip地址" aria-label="Permalink to “3、配置私有IP地址”">​</a></h4><p>在linux主机上的所有配置完成后，你需要配置其他设备（linux/windows的PC或笔记本）的DNS服务器以及默认网关，让它们的数据流可以指向linux主机。注意你不需要在linux主机上设置一个DNS服务器，从其他设备发出的每一个DNS请求都会通过上游的ISP自动转发到linux主机上。</p><p>如果你的其他设备上用的系统是linux，你可以通过以下命令来更改他们的默认网关和DNS服务器。假设你的网段是192.168.1.0/24的私有IP地址网段，linux主机上绑定的IP地址是192.168.1.1。</p><pre><code>$ sudo ip route del default
$ sudo ip route add default via 192.168.1.1
$ sudo sh -c &quot;echo &#39;nameserver 192.168.1.1&#39; &gt; /etc/resolv.conf&quot;
</code></pre><p>如果还有其他的linux设备，那么你可以重复以上命令。</p><p>如果你有windows设备，你可以通过控制面板的网络连接属性来更改默认网关和DNS服务器。</p><h4 id="_4、完整的脚本" tabindex="-1">4、完整的脚本 <a class="header-anchor" href="#_4、完整的脚本" aria-label="Permalink to “4、完整的脚本”">​</a></h4><p>这是一个在linux主机上设置网络连接共享的一个完整的脚本。WAN口（ppp0协议）需要根据你具体的网络接口协议来替换。</p><pre><code>$ sudo vi /usr/local/bin/ishare
</code></pre><hr><pre><code>#!/bin/bash

## Internet connection shating script

sysctl -w net.ipv4.ip_forward=1
sysctl -p
iptables -X
iptables -F
iptables -t nat -X
iptables -t nat -F
iptables -I INPUT -m state --state RELATED,ESTABLISHED -j ACCEPT
iptables -I FORWARD  -m state --state RELATED,ESTABLISHED -j ACCEPT
iptables -t nat -I POSTROUTING -o ppp0 -j MASQUERADE
</code></pre><p>保存以上的脚本到/usr/local/bin/ishare，然后添加可执行权限通过执行下面的命令。</p><pre><code>$ sudo chmox +x /usr/local/bin/ishare
</code></pre><p>如果你需要这个脚本开机启动，你需要在/etc/rc.local文件中执行这个脚本，并在该文件中的&quot;exit 0&quot;之前添加下面一行。</p><pre><code>/usr/local/bin/ishare
</code></pre><hr>`,41)),l("p",null,[e[1]||(e[1]=t("via: ",-1)),i(n,{href:"http://xmodulo.com/2014/06/internet-connection-sharing-iptables-linux.html"},{default:a(()=>[...e[0]||(e[0]=[t("http://xmodulo.com/2014/06/internet-connection-sharing-iptables-linux.html",-1)])]),_:1})]),l("p",null,[e[4]||(e[4]=t("译者：",-1)),i(n,{href:"https://github.com/yujianxuechuan"},{default:a(()=>[...e[2]||(e[2]=[t("yujianxuechuan",-1)])]),_:1}),e[5]||(e[5]=t(" 校对：",-1)),i(n,{href:"https://github.com/wxy"},{default:a(()=>[...e[3]||(e[3]=[t("wxy",-1)])]),_:1})]),l("p",null,[e[8]||(e[8]=t("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[6]||(e[6]=[t("LCTT",-1)])]),_:1}),e[9]||(e[9]=t(" 原创翻译，",-1)),i(n,{href:"http://linux.cn/"},{default:a(()=>[...e[7]||(e[7]=[t("Linux中国",-1)])]),_:1}),e[10]||(e[10]=t(" 荣誉推出",-1))])])}const f=o(d,[["render",h]]);export{A as __pageData,f as default};
